float ocv_from_soc(float soc, float T_C) {
    float T_K = T_C + 273.15;
    float eps = 1e-9;
    float soc_shift = soc - pow(0.1, 3);

    float denom = fmaxf(1.0 - soc_shift + C4, eps);
    float numer = fmaxf(C1 * soc_shift + C3, eps);

    float log_term = logf(numer / denom);

    return V0 + (C2 * (R * T_K / F) * log_term);
}


